  p.locator('#generateButton').click();p.locator('#genStyle').select_option('arc');p.locator('#genSeed').fill('69');p.locator('#genStart').click();p.wait_for_function('PulseApp.pendingGeneration&&document.getElementById("genConfirm")',timeout=120000);idle()
  ok('Advanced generation builds five preview charts without changing library',p.evaluate('PulseApp.pendingGeneration.charts.length===5&&JSON.stringify(PulseApp.song.charts)===beforePreview'))
  p.locator('#genCancel').click()
