  ok('Backup includes auto-import preferences and exact audio identity',p.evaluate('v6Backup.settings.autoMapImport===true&&v6Backup.songs.find(s=>s.id===musicID).audioHash===fixtureHashes["NEON_STEPS_128_ORIGINAL.wav"]'))
